dataSet.query:
// !!! ИСПОЛЬЗУЮТСЯ ТЕГИ !!! ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ Сегменты.Номенклатура КАК Номенклатура, Сегменты.Характеристика КАК Характеристика, ИСТИНА КАК ИспользуетсяОтборПоСегментуНоменклатуры ПОМЕСТИТЬ ОтборПоСегментуНоменклатуры ИЗ РегистрСведений.НоменклатураСегмента КАК Сегменты {ГДЕ Сегменты.Сегмент.* КАК СегментНоменклатуры, Сегменты.Номенклатура.* КАК Номенклатура, Сегменты.Характеристика.* КАК Характеристика}
ИНДЕКСИРОВАТЬ ПО Номенклатура, Характеристика, ИспользуетсяОтборПоСегментуНоменклатуры ;
//////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ Выпуск.Организация КАК Организация, ВЫБОР КОГДА НЕ Константы.ИспользоватьУправлениеПроизводством2_2 ТОГДА НЕОПРЕДЕЛЕНО КОГДА Аналитика.ТипМестаХранения = ЗНАЧЕНИЕ(Перечисление.ТипыМестХранения.Подразделение) ТОГДА Аналитика.Подразделение КОГДА Аналитика.ТипМестаХранения = ЗНАЧЕНИЕ(Перечисление.ТипыМестХранения.Партнер) ТОГДА Аналитика.Партнер ИНАЧЕ Аналитика.СкладскаяТерритория.Подразделение КОНЕЦ КАК ПодразделениеПродукции, ВЫБОР КОГДА НЕ РеквизитыВыпуска21.Ссылка ЕСТЬ NULL И НЕ Выпуск.АналитикаУчетаПродукции = ЗНАЧЕНИЕ(Справочник.КлючиАналитикиУчетаНоменклатуры.ПустаяСсылка) ТОГДА Выпуск.АналитикаУчетаПродукции ИНАЧЕ Выпуск.АналитикаУчетаНоменклатуры КОНЕЦ КАК АналитикаПродукции, Выпуск.Подразделение КАК ПодразделениеВыпуска, Аналитика.Номенклатура КАК Продукция, Аналитика.Характеристика КАК ХарактеристикаПродукции, Аналитика.Назначение КАК НазначениеПродукции, Аналитика.Серия КАК СерияПродукции, ВЫБОР КОГДА Выпуск.Заказ = НЕОПРЕДЕЛЕНО ТОГДА НЕОПРЕДЕЛЕНО //++ НЕ УТКА КОГДА Выпуск.Заказ ССЫЛКА Документ.ЗаказДавальца ТОГДА Выпуск.Регистратор //-- НЕ УТКА ИНАЧЕ Выпуск.Заказ КОНЕЦ КАК ЗаказНаПроизводство, Выпуск.Регистратор КАК Регистратор, ВЫБОР КОГДА &ЕдиницыКоличества = 0 ТОГДА Выпуск.Количество КОГДА &ЕдиницыКоличества = 1 ТОГДА ВЫБОР КОГДА Аналитика.Номенклатура.КоэффициентЕдиницыДляОтчетов <> 0 ТОГДА Выпуск.Количество / Аналитика.Номенклатура.КоэффициентЕдиницыДляОтчетов ИНАЧЕ 0 КОНЕЦ КОНЕЦ КАК КоличествоПродукции {ВЫБРАТЬ Организация.*, ПодразделениеПродукции.*, ПодразделениеВыпуска.*, Продукция.*, ХарактеристикаПродукции.*, НазначениеПродукции.*, СерияПродукции.*, ЗаказНаПроизводство.*, Регистратор.*, КоличествоПродукции} ИЗ РегистрНакопления.ВыпускПродукции КАК Выпуск ЛЕВОЕ СОЕДИНЕНИЕ Справочник.КлючиАналитикиУчетаНоменклатуры КАК Аналитика ПО Выпуск.АналитикаУчетаНоменклатуры = Аналитика.Ссылка ЛЕВОЕ СОЕДИНЕНИЕ Константы КАК Константы ПО (ИСТИНА) ЛЕВОЕ СОЕДИНЕНИЕ Документ.ВыпускПродукции КАК РеквизитыВыпуска21 ПО Выпуск.Регистратор = РеквизитыВыпуска21.Ссылка ГДЕ (Выпуск.Период МЕЖДУ &НачалоПериода И &КонецПериода ИЛИ &КонецПериода = ДАТАВРЕМЯ(1,1,1))
{ГДЕ Выпуск.Организация.*, Аналитика.Номенклатура.* КАК Продукция, Аналитика.Характеристика.* КАК ХарактеристикаПродукции, Аналитика.Назначение.* КАК НазначениеПродукции, Аналитика.Серия.* КАК СерияПродукции, Выпуск.Регистратор.*, Выпуск.Подразделение.* КАК ПодразделениеВыпуска, (АналитикаУчетаНоменклатуры.Номенклатура, АналитикаУчетаНоменклатуры.Характеристика) В (ВЫБРАТЬ ОтборПоСегментуНоменклатуры.Номенклатура, ОтборПоСегментуНоменклатуры.Характеристика ИЗ ОтборПоСегментуНоменклатуры ГДЕ ОтборПоСегментуНоменклатуры.ИспользуетсяОтборПоСегментуНоменклатуры = &ИспользуетсяОтборПоСегментуНоменклатуры)}

item.query:
// !!! ИСПОЛЬЗУЮТСЯ ТЕГИ !!! ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ Сегменты.Номенклатура КАК Номенклатура, Сегменты.Характеристика КАК Характеристика, ИСТИНА КАК ИспользуетсяОтборПоСегментуНоменклатуры ПОМЕСТИТЬ ОтборПоСегментуНоменклатуры ИЗ РегистрСведений.НоменклатураСегмента КАК Сегменты {ГДЕ Сегменты.Сегмент.* КАК СегментНоменклатуры, Сегменты.Номенклатура.* КАК Номенклатура, Сегменты.Характеристика.* КАК Характеристика}
ИНДЕКСИРОВАТЬ ПО Номенклатура, Характеристика, ИспользуетсяОтборПоСегментуНоменклатуры ; //////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ ДД.АналитикаУчетаНоменклатуры КАК АналитикаУчетаНоменклатуры ПОМЕСТИТЬ ВозвратныеОтходы ИЗ РегистрНакопления.СебестоимостьТоваров КАК ДД ГДЕ (ДД.Период МЕЖДУ &НачалоПериода И &КонецПериода ИЛИ &КонецПериода = ДАТАВРЕМЯ(1,1,1)) И ДД.ВидДвижения = ЗНАЧЕНИЕ(ВидДвиженияНакопления.Приход) И ДД.Количество < 0 И ДД.ХозяйственнаяОперация = ЗНАЧЕНИЕ(Перечисление.ХозяйственныеОперации.ВыпускПродукцииФиксированнаяСтоимость)
ИНДЕКСИРОВАТЬ ПО АналитикаУчетаНоменклатуры ; //////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ Партии.Период, Партии.Регистратор, Партии.АналитикаУчетаНоменклатуры, Партии.ВидЗапасов, Партии.ДокументПоступления, Партии.КорАналитикаУчетаНоменклатуры, СУММА( ВЫБОР КОГДА &ДанныеПоСебестоимости = 1 ТОГДА Партии.Стоимость КОГДА &ДанныеПоСебестоимости = 2 ИЛИ &ДанныеПоСебестоимости = 3 ТОГДА Партии.СтоимостьБезНДС КОГДА &ДанныеПоСебестоимости = 4 ТОГДА Партии.СтоимостьРегл +(ВЫБОР КОГДА Партии.АналитикаУчетаПартий.НалогообложениеНДС В ( ЗНАЧЕНИЕ(Перечисление.ТипыНалогообложенияНДС.ПродажаНеОблагаетсяНДС), ЗНАЧЕНИЕ(Перечисление.ТипыНалогообложенияНДС.ПродажаОблагаетсяЕНВД)) ТОГДА Партии.НДСРегл ИНАЧЕ 0 КОНЕЦ) ИНАЧЕ Партии.СтоимостьБезНДС КОНЕЦ) КАК Стоимость ПОМЕСТИТЬ ПартииРасходов ИЗ РегистрНакопления.ПартииРасходовНаСебестоимостьТоваров КАК Партии ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.РасчетСебестоимостиТоваров.Организации КАК РасчетСебестоимости ПО НАЧАЛОПЕРИОДА(Партии.Период, МЕСЯЦ) = НАЧАЛОПЕРИОДА(РасчетСебестоимости.Ссылка.Дата, МЕСЯЦ) И Партии.Организация = РасчетСебестоимости.Организация И РасчетСебестоимости.Ссылка.Проведен И РасчетСебестоимости.Ссылка.МетодОценки = ЗНАЧЕНИЕ(Перечисление.МетодыОценкиСтоимостиТоваров.ФИФОСкользящаяОценка) ГДЕ (Партии.Период МЕЖДУ &НачалоПериода И &КонецПериода ИЛИ &КонецПериода = ДАТАВРЕМЯ(1,1,1)) И Партии.ВидДвижения = ЗНАЧЕНИЕ(ВидДвиженияНакопления.Расход) И (Партии.Регистратор ССЫЛКА Документ.ВыпускПродукции //++ НЕ УТКА ИЛИ Партии.Регистратор ССЫЛКА Документ.ОтчетДавальцу //-- НЕ УТКА ИЛИ Партии.Регистратор ССЫЛКА Документ.ПоступлениеОтПереработчика)
СГРУППИРОВАТЬ ПО Партии.Период, Партии.Регистратор, Партии.АналитикаУчетаНоменклатуры, Партии.ВидЗапасов, Партии.ДокументПоступления, Партии.КорАналитикаУчетаНоменклатуры ; //////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ Партии.Период, Партии.Регистратор, Партии.АналитикаУчетаПродукции, Партии.ДокументВыпуска, Партии.КорАналитикаУчетаПродукции, СУММА( ВЫБОР КОГДА &ДанныеПоСебестоимости = 1 ТОГДА Партии.Стоимость КОГДА &ДанныеПоСебестоимости = 2 ИЛИ &ДанныеПоСебестоимости = 3 ТОГДА Партии.СтоимостьБезНДС КОГДА &ДанныеПоСебестоимости = 4 ТОГДА Партии.СтоимостьРегл +(ВЫБОР КОГДА Партии.АналитикаУчетаПартий.НалогообложениеНДС В ( ЗНАЧЕНИЕ(Перечисление.ТипыНалогообложенияНДС.ПродажаНеОблагаетсяНДС), ЗНАЧЕНИЕ(Перечисление.ТипыНалогообложенияНДС.ПродажаОблагаетсяЕНВД)) ТОГДА Партии.НДСРегл ИНАЧЕ 0 КОНЕЦ) ИНАЧЕ Партии.СтоимостьБезНДС КОНЕЦ) КАК Стоимость ПОМЕСТИТЬ ПартииЗатрат ИЗ РегистрНакопления.ПартииЗатратНаВыпуск КАК Партии ВНУТРЕННЕЕ СОЕДИНЕНИЕ Документ.РасчетСебестоимостиТоваров.Организации КАК РасчетСебестоимости ПО НАЧАЛОПЕРИОДА(Партии.Период, МЕСЯЦ) = НАЧАЛОПЕРИОДА(РасчетСебестоимости.Ссылка.Дата, МЕСЯЦ) И Партии.Организация = РасчетСебестоимости.Организация И РасчетСебестоимости.Ссылка.Проведен И РасчетСебестоимости.Ссылка.МетодОценки = ЗНАЧЕНИЕ(Перечисление.МетодыОценкиСтоимостиТоваров.ФИФОСкользящаяОценка) ГДЕ (Партии.Период МЕЖДУ &НачалоПериода И &КонецПериода ИЛИ &КонецПериода = ДАТАВРЕМЯ(1,1,1)) И Партии.ВидДвижения = ЗНАЧЕНИЕ(ВидДвиженияНакопления.Расход) И (Партии.Регистратор ССЫЛКА Документ.ВыпускПродукции //++ НЕ УТКА ИЛИ Партии.Регистратор ССЫЛКА Документ.ОтчетДавальцу //-- НЕ УТКА ИЛИ Партии.Регистратор ССЫЛКА Документ.ПоступлениеОтПереработчика)
СГРУППИРОВАТЬ ПО Партии.Период, Партии.Регистратор, Партии.АналитикаУчетаПродукции, Партии.ДокументВыпуска, Партии.КорАналитикаУчетаПродукции ; //////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ Партии.Период, Партии.Регистратор, Партии.Организация, Партии.АналитикаУчетаНоменклатуры, Партии.ВидЗапасов, Партии.ДокументПоступления, Партии.ЗаказНаПроизводство, Партии.СтатьяКалькуляции, Партии.АналитикаУчетаПродукции, Партии.КорВидЗапасов, Партии.Продукция, Партии.ХарактеристикаПродукции, СУММА(Партии.Количество) КАК Количество, СУММА( ВЫБОР КОГДА &ДанныеПоСебестоимости = 1 ТОГДА Партии.Стоимость КОГДА &ДанныеПоСебестоимости = 2 ИЛИ &ДанныеПоСебестоимости = 3 ТОГДА Партии.СтоимостьБезНДС КОГДА &ДанныеПоСебестоимости = 4 ТОГДА Партии.СтоимостьРегл +(ВЫБОР КОГДА Партии.АналитикаУчетаПартий.НалогообложениеНДС В ( ЗНАЧЕНИЕ(Перечисление.ТипыНалогообложенияНДС.ПродажаНеОблагаетсяНДС), ЗНАЧЕНИЕ(Перечисление.ТипыНалогообложенияНДС.ПродажаОблагаетсяЕНВД)) ТОГДА Партии.НДСРегл ИНАЧЕ 0 КОНЕЦ) ИНАЧЕ Партии.СтоимостьБезНДС КОНЕЦ) КАК Стоимость ПОМЕСТИТЬ ПартииНЗП ИЗ РегистрНакопления.ПартииНезавершенногоПроизводства КАК Партии ЛЕВОЕ СОЕДИНЕНИЕ Константы КАК Константы ПО (ИСТИНА) ГДЕ (Партии.Период МЕЖДУ &НачалоПериода И &КонецПериода ИЛИ &КонецПериода = ДАТАВРЕМЯ(1,1,1)) И Партии.ВидДвижения = ЗНАЧЕНИЕ(ВидДвиженияНакопления.Расход) И (Партии.ВидЗапасов = ЗНАЧЕНИЕ(Справочник.ВидыЗапасов.ПустаяСсылка) ИЛИ (Партии.ВидЗапасов.ТипЗапасов <> ЗНАЧЕНИЕ(Перечисление.ТипыЗапасов.МатериалДавальца) И Партии.ВидЗапасов.ТипЗапасов <> ЗНАЧЕНИЕ(Перечисление.ТипыЗапасов.ПродукцияДавальца))) И (Партии.Регистратор ССЫЛКА Документ.ВыпускПродукции //++ НЕ УТКА ИЛИ Партии.Регистратор ССЫЛКА Документ.ОтчетДавальцу //-- НЕ УТКА ИЛИ Партии.Регистратор ССЫЛКА Документ.ПоступлениеОтПереработчика) И (НЕ Константы.ПартионныйУчетВерсии22 ИЛИ Партии.Период < Константы.ДатаПереходаНаПартионныйУчетВерсии22)
СГРУППИРОВАТЬ ПО Партии.Период, Партии.Регистратор, Партии.Организация, Партии.АналитикаУчетаНоменклатуры, Партии.ВидЗапасов, Партии.ДокументПоступления, Партии.ЗаказНаПроизводство, Партии.СтатьяКалькуляции, Партии.АналитикаУчетаПродукции, Партии.КорВидЗапасов, Партии.Продукция, Партии.ХарактеристикаПродукции ; //////////////////////////////////////////////////////////////////////////////// ВЫБРАТЬ РАЗРЕШЕННЫЕ ЗатратыНЗП.Организация КАК Организация, НЕОПРЕДЕЛЕНО КАК ПодразделениеПродукции, ЗатратыНЗП.АналитикаУчетаПродукции КАК АналитикаПродукции, АналитикаВыпуска.Номенклатура КАК Продукция, АналитикаВыпуска.Характеристика КАК ХарактеристикаПродукции, АналитикаВыпуска.Номенклатура.ЕдиницаИзмерения КАК ЕдиницаИзмеренияПродукции, АналитикаВыпуска.Серия КАК СерияПродукции, ЗатратыНЗП.СтатьяКалькуляции КАК СтатьяКалькуляции, "Партии" КАК ВидЗатрат, Аналитика.Номенклатура КАК Затрата, Аналитика.Характеристика КАК ХарактеристикаЗатраты, Аналитика.Серия КАК СерияЗатраты,
ВЫБОР КОГДА &ЕдиницыКоличества = 0 ТОГДА Аналитика.Номенклатура.ЕдиницаИзмерения КОГДА &ЕдиницыКоличества = 1 ТОГДА Аналитика.Номенклатура.ЕдиницаДляОтчетов КОНЕЦ КАК ЕдиницаИзмеренияЗатраты,
Аналитика.МестоХранения КАК Подразделение, (ВЫБОР КОГДА ЗатратыНЗП.ЗаказНаПроизводство ЕСТЬ NULL ТОГДА НЕОПРЕДЕЛЕНО КОГДА ЗатратыНЗП.ЗаказНаПроизводство ССЫЛКА Справочник.РесурсныеСпецификации Тогда НЕОПРЕДЕЛЕНО //++ НЕ УТКА КОГДА ЗатратыНЗП.Регистратор ССЫЛКА Документ.ОтчетДавальцу ТОГДА ЗатратыНЗП.Регистратор //-- НЕ УТКА ИНАЧЕ ЗатратыНЗП.ЗаказНаПроизводство КОНЕЦ) КАК ЗаказНаПроизводство, ЕСТЬNULL(ЗатратыНЗП.ВидЗапасов.ГруппаПродукции, ЗНАЧЕНИЕ(Справочник.ГруппыАналитическогоУчетаНоменклатуры.ПустаяСсылка)) КАК ГруппаПродукции, ЗатратыНЗП.КорВидЗапасов КАК ВидЗапасов, АналитикаВыпуска.Назначение КАК НазначениеПродукции,
ВЫБОР КОГДА &ЕдиницыКоличества = 0 ТОГДА ЗатратыНЗП.Количество КОГДА &ЕдиницыКоличества = 1 ТОГДА ВЫБОР КОГДА Аналитика.Номенклатура.КоэффициентЕдиницыДляОтчетов <> 0 ТОГДА ЗатратыНЗП.Количество / Аналитика.Номенклатура.КоэффициентЕдиницыДляОтчетов ИНАЧЕ 0 КОНЕЦ КОНЕЦ КАК КоличествоЗатрат,
ВЫБОР КОГДА ЗатратыНЗП.Регистратор ССЫЛКА Документ.ПоступлениеОтПереработчика И ЗатратыНЗП.ВидЗапасов.ТипЗапасов = ЗНАЧЕНИЕ(Перечисление.ТипыЗапасов.Услуга) ТОГДА ЗатратыНЗП.Стоимость КОГДА РасчетСебестоимости.Ссылка ЕСТЬ NULL ТОГДА ВЫБОР КОГДА &ДанныеПоСебестоимости = 1 ТОГДА ЗатратыНЗП.Количество * (СтоимостьЗатрат.Стоимость + СтоимостьЗатрат.СтоимостьДопРасходы) КОГДА &ДанныеПоСебестоимости = 2 ТОГДА ЗатратыНЗП.Количество * (СтоимостьЗатрат.СтоимостьБезНДС + СтоимостьЗатрат.СтоимостьДопРасходыБезНДС) КОГДА &ДанныеПоСебестоимости = 3 ТОГДА ЗатратыНЗП.Количество * (СтоимостьЗатрат.СтоимостьУпр + СтоимостьЗатрат.ДопРасходыУпр) КОГДА &ДанныеПоСебестоимости = 4 ТОГДА ЗатратыНЗП.Количество * СтоимостьЗатрат.СтоимостьРегл ИНАЧЕ ВЫБОР КОГДА &ПоПредприятию ТОГДА ЗатратыНЗП.Количество * (СтоимостьЗатрат.СтоимостьБезНДС + СтоимостьЗатрат.СтоимостьДопРасходыБезНДС) ИНАЧЕ ЗатратыНЗП.Количество * (СтоимостьЗатрат.СтоимостьУпр + СтоимостьЗатрат.ДопРасходыУпр) КОНЕЦ КОНЕЦ ИНАЧЕ ЗатратыНЗП.Стоимость + ЕСТЬNULL(ПартииРасходов.Стоимость, 0) + ЕСТЬNULL(ПартииЗатрат.Стоимость, 0) КОНЕЦ КАК СтоимостьЗатрат, ЗатратыНЗП.Регистратор КАК Регистратор ИЗ ПартииНЗП КАК ЗатратыНЗП ЛЕВОЕ СОЕДИНЕНИЕ ВозвратныеОтходы КАК ВозвратныеОтходы ПО ЗатратыНЗП.АналитикаУчетаНоменклатуры = ВозвратныеОтходы.АналитикаУчетаНоменклатуры ЛЕВОЕ СОЕДИНЕНИЕ Справочник.КлючиАналитикиУчетаНоменклатуры КАК Аналитика ПО ЗатратыНЗП.АналитикаУчетаНоменклатуры = Аналитика.Ссылка ВНУТРЕННЕЕ СОЕДИНЕНИЕ Справочник.КлючиАналитикиУчетаНоменклатуры КАК АналитикаВыпуска ПО ЗатратыНЗП.АналитикаУчетаПродукции = АналитикаВыпуска.Ссылка ЛЕВОЕ СОЕДИНЕНИЕ Константы КАК Константы ПО (ИСТИНА) ЛЕВОЕ СОЕДИНЕНИЕ РегистрСведений.СтоимостьТоваров КАК СтоимостьЗатрат ПО ВЫБОР КОГДА Константы.УчитыватьСебестоимостьТоваровПоВидамЗапасов ТОГДА ЗатратыНЗП.АналитикаУчетаНоменклатуры = СтоимостьЗатрат.АналитикаУчетаНоменклатуры ИНАЧЕ ЗатратыНЗП.АналитикаУчетаНоменклатуры.Номенклатура = СтоимостьЗатрат.АналитикаУчетаНоменклатуры.Номенклатура И ЗатратыНЗП.АналитикаУчетаНоменклатуры.Характеристика = СтоимостьЗатрат.АналитикаУчетаНоменклатуры.Характеристика И ЗатратыНЗП.АналитикаУчетаНоменклатуры.Серия = СтоимостьЗатрат.АналитикаУчетаНоменклатуры.Серия И ЗатратыНЗП.АналитикаУчетаНоменклатуры.МестоХранения = СтоимостьЗатрат.АналитикаУчетаНоменклатуры.МестоХранения И ЗатратыНЗП.АналитикаУчетаНоменклатуры.СтатьяКалькуляции = СтоимостьЗатрат.АналитикаУчетаНоменклатуры.СтатьяКалькуляции КОНЕЦ И ЗатратыНЗП.Организация = СтоимостьЗатрат.Организация И (СтоимостьЗатрат.Период = НАЧАЛОПЕРИОДА(ЗатратыНЗП.Период, МЕСЯЦ)) И (ЗатратыНЗП.ВидЗапасов = СтоимостьЗатрат.ВидЗапасов ИЛИ НЕ Константы.УчитыватьСебестоимостьТоваровПоВидамЗапасов) И (ВЫБОР КОГДА ЗатратыНЗП.Количество < 0 И НЕ ВозвратныеОтходы.АналитикаУчетаНоменклатуры ЕСТЬ NULL И СтоимостьЗатрат.РазделУчета = ЗНАЧЕНИЕ(Перечисление.РазделыУчетаСебестоимостиТоваров.ПустаяСсылка) ТОГДА ИСТИНА КОГДА (ЗатратыНЗП.Количество > 0 ИЛИ ВозвратныеОтходы.АналитикаУчетаНоменклатуры ЕСТЬ NULL) И СтоимостьЗатрат.РазделУчета <> ЗНАЧЕНИЕ(Перечисление.РазделыУчетаСебестоимостиТоваров.ТоварыПереданныеПереработчику) И СтоимостьЗатрат.РазделУчета <> ЗНАЧЕНИЕ(Перечисление.РазделыУчетаСебестоимостиТоваров.ПустаяСсылка) ТОГДА ИСТИНА ИНАЧЕ ЛОЖЬ КОНЕЦ) ЛЕВОЕ СОЕДИНЕНИЕ ПартииРасходов КАК ПартииРасходов ПО ПартииРасходов.Период = ЗатратыНЗП.Период И ПартииРасходов.Регистратор = ЗатратыНЗП.Регистратор И ПартииРасходов.АналитикаУчетаНоменклатуры = ЗатратыНЗП.АналитикаУчетаНоменклатуры И ПартииРасходов.ВидЗапасов = ЗатратыНЗП.ВидЗапасов И ПартииРасходов.ДокументПоступления = ЗатратыНЗП.ДокументПоступления И ПартииРасходов.КорАналитикаУчетаНоменклатуры = ЗатратыНЗП.АналитикаУчетаПродукции ЛЕВОЕ СОЕДИНЕНИЕ ПартииЗатрат КАК ПартииЗатрат ПО ПартииЗатрат.Период = ЗатратыНЗП.Период И ПартииЗатрат.Регистратор = ЗатратыНЗП.Регистратор И ПартииЗатрат.АналитикаУчетаПродукции = ЗатратыНЗП.АналитикаУчетаНоменклатуры И ПартииЗатрат.ДокументВыпуска = ЗатратыНЗП.ДокументПоступления И ПартииЗатрат.КорАналитикаУчетаПродукции = ЗатратыНЗП.АналитикаУчетаПродукции ЛЕВОЕ СОЕДИНЕНИЕ Документ.РасчетСебестоимостиТоваров.Организации КАК РасчетСебестоимости ПО НАЧАЛОПЕРИОДА(ЗатратыНЗП.Период, МЕСЯЦ) = НАЧАЛОПЕРИОДА(РасчетСебестоимости.Ссылка.Дата, МЕСЯЦ) И ЗатратыНЗП.Организация = РасчетСебестоимости.Организация И РасчетСебестоимости.Ссылка.Проведен И РасчетСебестоимости.Ссылка.МетодОценки = ЗНАЧЕНИЕ(Перечисление.МетодыОценкиСтоимостиТоваров.ФИФОСкользящаяОценка) {ГДЕ ((ЗатратыНЗП.Продукция, ЗатратыНЗП.ХарактеристикаПродукции) В (ВЫБРАТЬ ОтборПоСегментуНоменклатуры.Номенклатура, ОтборПоСегментуНоменклатуры.Характеристика ИЗ ОтборПоСегментуНоменклатуры ГДЕ ОтборПоСегментуНоменклатуры.ИспользуетсяОтборПоСегментуНоменклатуры = &ИспользуетсяОтборПоСегментуНоменклатуры))}

// !!! ИСПОЛЬЗУЮТСЯ ТЕГИ !!!
ВЫБРАТЬ РАЗРЕШЕННЫЕ РАЗЛИЧНЫЕ Сегменты.Номенклатура КАК Номенклатура, Сегменты.Характеристика КАК Характеристика, ИСТИНА КАК ИспользуетсяОтборПоСегментуНоменклатуры ПОМЕСТИТЬ ОтборПоСегментуНоменклатуры ИЗ РегистрСведений.НоменклатураСегмента КАК Сегменты {ГДЕ Сегменты.Сегмент.* КАК СегментНоменклатуры, Сегменты.Номенклатура.* КАК Номенклатура, Сегменты.Характеристика.* КАК Характеристика}
ИНДЕКСИРОВАТЬ ПО Номенклатура, Характеристика, ИспользуетсяОтборПоСегментуНоменклатуры ;
ВЫБРАТЬ РАЗЛИЧНЫЕ ДД.Регистратор, ДД.АналитикаУчетаНоменклатуры, ДД.ВидЗапасов, ДД.КорАналитикаУчетаНоменклатуры, ДД.КорВидЗапасов ПОМЕСТИТЬ РаботыДляДавальца ИЗ РегистрНакопления.СебестоимостьТоваров КАК ДД ВНУТРЕННЕЕ СОЕДИНЕНИЕ Справочник.КлючиАналитикиУчетаНоменклатуры КАК АналитикаВыпуска ПО АналитикаВыпуска.Ссылка = ДД.КорАналитикаУчетаНоменклатуры ЛЕВОЕ СОЕДИНЕНИЕ Константы КАК Константы ПО ИСТИНА ГДЕ (ДД.Период МЕЖДУ &НачалоПериода И &КонецПериода ИЛИ &КонецПериода = ДАТАВРЕМЯ(1,1,1)) И ДД.Активность И ДД.ТипЗаписи = ЗНАЧЕНИЕ(Перечисление.ТипыЗаписейПартий.Партия) И ДД.ХозяйственнаяОперация В (ЗНАЧЕНИЕ(Перечисление.ХозяйственныеОперации.ВыпускПродукции), ЗНАЧЕНИЕ(Перечисление.ХозяйственныеОперации.ВыпускПродукцииНаСклад), ЗНАЧЕНИЕ(Перечисление.ХозяйственныеОперации.ВыпускПродукцииВПодразделение)) И ДД.РазделУчета = ЗНАЧЕНИЕ(Перечисление.РазделыУчетаСебестоимостиТоваров.ПроизводственныеЗатраты) И ДД.КорАналитикаУчетаНоменклатуры <> ЗНАЧЕНИЕ(Справочник.КлючиАналитикиУчетаНоменклатуры.ПустаяСсылка) И Константы.ПартионныйУчетВерсии22 И ДД.Период >= Константы.ДатаПереходаНаПартионныйУчетВерсии22 {ГДЕ (АналитикаВыпуска.Номенклатура, АналитикаВыпуска.Характеристика) В ( ВЫБРАТЬ ОтборПоСегментуНоменклатуры.Номенклатура, ОтборПоСегментуНоменклатуры.Характеристика ИЗ ОтборПоСегментуНоменклатуры ГДЕ ОтборПоСегментуНоменклатуры.ИспользуетсяОтборПоСегментуНоменклатуры = &ИспользуетсяОтборПоСегментуНоменклатуры ) }
СГРУППИРОВАТЬ ПО ДД.Регистратор, ДД.АналитикаУчетаНоменклатуры, ДД.ВидЗапасов, ДД.КорАналитикаУчетаНоменклатуры, ДД.КорВидЗапасов
ИНДЕКСИРОВАТЬ ПО Регистратор, КорАналитикаУчетаНоменклатуры, КорВидЗапасов ;
